import json, os
import numpy as np
from scipy.optimize import curve_fit

TASK = "/task"
OUT = "/work/results.json"


def load(path):
    xs, ys = [], []
    with open(path) as fh:
        lines = [l.strip() for l in fh if l.strip()]
    for line in lines[1:]:
        p = line.split(",")
        xs.append(float(p[0]))
        ys.append(float(p[1]))
    return np.array(xs, float), np.array(ys, float)


def model(x, bottom, top, logic50, hill):
    e = np.clip((logic50 - np.log10(x)) * hill, -60.0, 60.0)
    return bottom + (top - bottom) / (1.0 + np.power(10.0, e))


def fit4pl(path):
    x, y = load(path)
    order = np.argsort(x)
    x, y = x[order], y[order]
    descending = y[-1] < y[0]
    starts = [-1.0, -0.5, -2.0, -3.0] if descending else [1.0, 0.5, 2.0, 3.0]
    best = None
    for h0 in starts:
        lo, hi = float(y.min()), float(y.max())
        p0 = [hi, lo, float(np.mean(np.log10(x))), h0] if descending else [lo, hi, float(np.mean(np.log10(x))), h0]
        try:
            popt, _ = curve_fit(model, x, y, p0=p0, maxfev=200000)
        except Exception:
            continue
        ss = float(np.sum((y - model(x, *popt)) ** 2))
        if best is None or ss < best[1]:
            best = (popt, ss)
    if best is None:
        raise SystemExit("fit failed")
    popt, _ss = best
    bottom, top, logic50, hill = [float(v) for v in popt]
    return {
        "ic50": 10.0 ** logic50,
        "hill_abs": abs(hill),
        "top": max(bottom, top),
        "bottom": min(bottom, top),
    }


files = set(os.listdir(TASK))
p = lambda n: os.path.join(TASK, n)
res = {}
if "agonist_a.csv" in files:
    a = fit4pl(p("agonist_a.csv"))
    b = fit4pl(p("agonist_b.csv"))
    res = {
        "ec50_a_nM": a["ic50"],
        "ec50_b_nM": b["ic50"],
        "more_potent": "A" if a["ic50"] < b["ic50"] else "B",
        "fold_shift": max(a["ic50"], b["ic50"]) / min(a["ic50"], b["ic50"]),
    }
elif "agonist_x.csv" in files:
    x = fit4pl(p("agonist_x.csv"))
    y = fit4pl(p("agonist_y.csv"))
    res = {
        "emax_x": x["top"],
        "emax_y": y["top"],
        "partial_agonist": "X" if x["top"] < y["top"] else "Y",
        "more_potent": "X" if x["ic50"] < y["ic50"] else "Y",
    }
elif "assay_curve_1.csv" in files:
    c1 = fit4pl(p("assay_curve_1.csv"))
    c2 = fit4pl(p("assay_curve_2.csv"))
    res = {
        "hill_slope_abs_1": c1["hill_abs"],
        "hill_slope_abs_2": c2["hill_abs"],
        "ic50_1_nM": c1["ic50"],
        "ic50_2_nM": c2["ic50"],
    }
elif "compound_a_nM.csv" in files:
    a = fit4pl(p("compound_a_nM.csv"))
    b = fit4pl(p("compound_b_uM.csv"))
    b_nm = b["ic50"] * 1000.0
    res = {
        "ec50_a_nM": a["ic50"],
        "ec50_b_uM": b["ic50"],
        "fold_shift": max(a["ic50"], b_nm) / min(a["ic50"], b_nm),
        "more_potent": "A" if a["ic50"] < b_nm else "B",
    }

with open(OUT, "w") as fh:
    json.dump(res, fh)
